/// New splash screen image (embedded, no asset file needed).
class SplashImage extends StatelessWidget {
  final BoxFit fit;
  const SplashImage({super.key, this.fit = BoxFit.cover});

  @override
  Widget build(BuildContext context) {
    final Uint8List bytes = base64Decode(_kSplashBase64);
    return Image.memory(
      bytes,
      fit: fit,
      gaplessPlayback: true,
    );
  }
}
